import logging
from taf.converters.base import base
from robot.utils.robottypes import is_truthy
from .factory import TsharkConverterFactory

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class tshark(base):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    _factory = TsharkConverterFactory()

    def create_tshark_converter(
            self,
            name,
            file_path_pattern,
            output_extension,
            output_directory=None,
            options=None,
            tshark_path=None,
            sudo_password=None,
            binary=False):

        """
        Create Tshark Converter from given configuration

        :param str name: name of collector
        :param str file_path_pattern: source pcap file name or name pattern with path which is stored locally.
        :param str output_directory: (optional) converted file storage directory, default: same as input file path.
        :param str output_extension: converted file extension which will store locally.
        :param str options: (optional) tshark options (except for "-r"), default: empty string
        :param str tshark_path: (optional) path of tshark executable, default value: "tshark"
        :param str sudo_password: (optional) password for sudo
        :param bool binary: (optional) write undecoded packets to a file via tshark "-w" option
         (e. g. filtering pcap to pcap), if True, otherwise write decoded packets to a file via tshark ouput redirection
         (e. g. converting pcap to PDML), default: False

        For more detail on Converters please refer:
        https://confluence.int.net.nokia.com/display/CV/Converters
        """

        configuration = {
            'file_path_pattern': file_path_pattern,
            'output_extension': output_extension,
            'name': name}

        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["output_directory", "options", "tshark_path", "sudo_password", "binary"]:
                if parameter_name == "binary":
                    parameter_value = is_truthy(parameter_value)
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value
        logger.info("Creating Converter with alias: " + name)
        converter = self._factory.create(
            configuration=configuration,
            existing_arguments={})
        logger.info(name + " converter created successfully")
        self.set_alias(name, converter)
